import sys, json

data = json.load(sys.stdin)
with open('after-cpm-packages.json', 'w') as f:
    json.dump(data, f, indent=2)

baseline = json.load(open('baseline-packages.json'))

# Build lookup: project_name -> framework -> {pkg: version}
def build_lookup(d):
    result = {}
    for p in d['projects']:
        name = p['path'].split('/')[-1]
        result[name] = {}
        for fw in p['frameworks']:
            result[name][fw['framework']] = {pkg['id']: pkg['resolvedVersion'] for pkg in fw['topLevelPackages']}
    return result

before = build_lookup(baseline)
after = build_lookup(data)

changes = []
unchanged = []

for proj in sorted(after):
    for fw in sorted(after[proj]):
        for pkg in sorted(after[proj][fw]):
            v_after = after[proj][fw][pkg]
            v_before = before.get(proj, {}).get(fw, {}).get(pkg)
            if v_before is None:
                changes.append((proj, fw, pkg, 'N/A', v_after, 'Added'))
            elif v_before != v_after:
                changes.append((proj, fw, pkg, v_before, v_after, 'Version changed'))
            else:
                unchanged.append((proj, fw, pkg, v_after))

# Check for removed
for proj in sorted(before):
    for fw in sorted(before[proj]):
        for pkg in sorted(before[proj][fw]):
            if pkg not in after.get(proj, {}).get(fw, {}):
                changes.append((proj, fw, pkg, before[proj][fw][pkg], 'N/A', 'Removed'))

print('=== CHANGES ===')
if changes:
    for c in changes:
        print(f'  {c[0]} ({c[1]}): {c[2]} {c[3]} -> {c[4]} [{c[5]}]')
else:
    print('  None')

print(f'\n=== UNCHANGED: {len(unchanged)} packages ===')
for u in unchanged[:5]:
    print(f'  {u[0]} ({u[1]}): {u[2]} {u[3]}')
if len(unchanged) > 5:
    print(f'  ... and {len(unchanged)-5} more')
"

